// Alegra devuelve máximo 30 productos por llamada, así que el nodo anterior
// hace varias llamadas y entrega una página por cada una.
// Aquí las abrimos para quedar con un producto por item.

const productos = [];

for (const item of items) {
  const cuerpo = item.json;
  if (Array.isArray(cuerpo)) {
    productos.push(...cuerpo);
  } else if (Array.isArray(cuerpo.data)) {
    productos.push(...cuerpo.data);
  } else {
    productos.push(cuerpo);
  }
}

return productos.map((producto) => ({ json: producto }));

// Mismo desdoble que con los productos: una página por item, la abrimos.

const facturas = [];

for (const item of items) {
  const cuerpo = item.json;
  if (Array.isArray(cuerpo)) {
    facturas.push(...cuerpo);
  } else if (Array.isArray(cuerpo.data)) {
    facturas.push(...cuerpo.data);
  } else {
    facturas.push(cuerpo);
  }
}

return facturas.map((factura) => ({ json: factura }));

// ─── Puedes cambiar esto ──────────────────────────────────────────────
const MINIMO_POR_DEFECTO = 5;    // se usa cuando el producto no tiene mínimo en Alegra
const DIAS_DE_VENTA = 30;        // ventana para medir qué tan rápido se vende
const COBERTURA_CRITICA = 7;     // días de inventario por debajo de los cuales es crítico
const DIAS_A_CUBRIR = 30;        // para cuántos días quieres pedir
const MONEDA = 'COP';            // solo afecta cómo se ve la plata en el aviso
// ──────────────────────────────────────────────────────────────────────

// Fecha de hoy armada a mano, para que no se corra un día por la zona horaria.
const hoy = new Date();
const fechaCorte =
  hoy.getFullYear() +
  '-' + String(hoy.getMonth() + 1).padStart(2, '0') +
  '-' + String(hoy.getDate()).padStart(2, '0');

const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

// ── Paso 1: contar cuántas unidades se vendieron de cada producto ──
// Las líneas de una factura pueden traer el id del producto de dos formas,
// según la versión de la cuenta. Probamos ambas.
const vendidas = new Map();

for (const item of items) {
  const factura = item.json;
  const lineas = Array.isArray(factura.items) ? factura.items : [];
  for (const linea of lineas) {
    const id = String(linea.id ?? (linea.item && linea.item.id) ?? '');
    if (!id) continue;
    const cantidad = Number(linea.quantity ?? 0);
    if (!(cantidad > 0)) continue;
    vendidas.set(id, (vendidas.get(id) || 0) + cantidad);
  }
}

// Si ninguna factura trajo el detalle de líneas, no podemos calcular
// cobertura. El flujo sigue funcionando solo con el stock mínimo.
const hayDatosDeVenta = vendidas.size > 0;

// ── Paso 2: revisar producto por producto ──
const productos = $('Separar productos').all();
const alertas = [];

for (const p of productos) {
  const prod = p.json;
  const inv = prod.inventory;

  // Los servicios y todo lo que no maneje inventario no aplica.
  if (!inv) continue;

  const disponible = Number(inv.availableQuantity ?? 0);
  const costoUnitario = Number(inv.unitCost ?? 0);

  // El mínimo se configura por bodega y casi siempre viene vacío.
  // Sumamos los que sí estén puestos; si no hay ninguno, usamos el de arriba.
  const bodegas = Array.isArray(inv.warehouses) ? inv.warehouses : [];
  const minimosPuestos = bodegas
    .map((b) => b.minQuantity)
    .filter((m) => m !== null && m !== undefined && m !== '')
    .map(Number)
    .filter((m) => !Number.isNaN(m));

  const minimoConfigurado = minimosPuestos.length > 0;
  const minimo = minimoConfigurado
    ? minimosPuestos.reduce((a, b) => a + b, 0)
    : MINIMO_POR_DEFECTO;

  const vendido = vendidas.get(String(prod.id)) || 0;
  const promedioDiario = vendido / DIAS_DE_VENTA;
  const diasCobertura =
    promedioDiario > 0 ? Math.floor(disponible / promedioDiario) : null;

  // ── Paso 3: decidir si merece alerta y con qué urgencia ──
  let estado = null;
  if (disponible <= 0) {
    estado = 'Agotado';
  } else if (diasCobertura !== null && diasCobertura <= COBERTURA_CRITICA) {
    estado = 'Crítico';
  } else if (disponible < minimo) {
    estado = 'Bajo';
  }

  if (!estado) continue;

  // Cuánto pedir: lo que haga falta para llegar al mínimo, o para cubrir
  // los próximos DIAS_A_CUBRIR al ritmo al que se está vendiendo.
  const paraElMinimo = Math.max(minimo - disponible, 0);
  const paraLaDemanda = Math.max(
    Math.ceil(promedioDiario * DIAS_A_CUBRIR) - disponible,
    0
  );
  const sugerido = Math.max(paraElMinimo, paraLaDemanda, 1);

  const nombreBodega = bodegas.length
    ? bodegas.map((b) => b.name).filter(Boolean).join(', ')
    : 'Sin bodega';

  alertas.push({
    producto: prod.name || 'Producto sin nombre',
    productoId: String(prod.id),
    referencia: prod.reference || '',
    disponible,
    minimo,
    minimoConfigurado,
    sugerido,
    vendido,
    diasCobertura,
    costoReposicion: Math.round(sugerido * costoUnitario),
    costoTexto: plata(sugerido * costoUnitario),
    estado,
    bodega: nombreBodega,
    hayDatosDeVenta,
    fechaCorte,
  });
}

// Lo más urgente arriba: primero lo agotado, luego lo de menos cobertura.
const peso = { Agotado: 0, 'Crítico': 1, Bajo: 2 };
alertas.sort((a, b) => {
  if (peso[a.estado] !== peso[b.estado]) return peso[a.estado] - peso[b.estado];
  const ca = a.diasCobertura === null ? 9999 : a.diasCobertura;
  const cb = b.diasCobertura === null ? 9999 : b.diasCobertura;
  return ca - cb;
});

return alertas.map((a) => ({ json: a }));

// Junta todo en un solo mensaje. Si no hay nada urgente, no devuelve nada
// y el nodo de Telegram sencillamente no corre.

// Debe ser la misma moneda que pusiste en "Calcular qué reponer".
const MONEDA = 'COP';

const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

const urgentes = items
  .map((i) => i.json)
  .filter((a) => a.estado === 'Agotado' || a.estado === 'Crítico');

if (urgentes.length === 0) return [];

const lineas = urgentes.slice(0, 20).map((a) => {
  const cobertura =
    a.diasCobertura === null
      ? 'sin datos de venta'
      : 'te alcanza para ' + a.diasCobertura + ' día(s)';
  return (
    '• <b>' + a.producto + '</b> — quedan ' + a.disponible + ', ' + cobertura +
    '. Pedir ' + a.sugerido + ' (' + a.costoTexto + ')'
  );
});

const agotados = urgentes.filter((a) => a.estado === 'Agotado').length;
const total = urgentes.reduce((s, a) => s + a.costoReposicion, 0);

const encabezado =
  agotados > 0
    ? '<b>Tienes ' + agotados + ' producto(s) agotado(s)</b>'
    : '<b>Se te está acabando el inventario</b>';

const partes = [
  encabezado,
  '',
  ...lineas,
];

if (urgentes.length > 20) {
  partes.push('', 'Y ' + (urgentes.length - 20) + ' más. Míralos en Notion.');
}

partes.push('', 'Reponer todo esto te cuesta cerca de ' + plata(total) + '.');

return [{ json: { mensaje: partes.join('\n'), cantidad: urgentes.length } }];
